export type DegreeExamQuestionDetailKey =
  | "answer"
  | "point"
  | "translation"
  | "pitfalls";

export interface DegreeExamQuestion {
  id: string;
  number: number;
  prompt: string;
  options?: string[];
  analysis: Record<DegreeExamQuestionDetailKey, string>;
}

export interface DegreeExamSection {
  id: string;
  title: string;
  questionRange: string;
  score: number;
  instructions: string;
  sourceBasis: string[];
  material?: string[];
  materialTranslation?: string[];
  assistantTitle?: string;
  assistantItems?: string[];
  questions: DegreeExamQuestion[];
}

export interface DegreeExamPaper {
  id: string;
  title: string;
  badge: string;
  description: string;
  durationMinutes: number;
  totalScore: number;
  textbookBasis: string;
  examBasis: string;
  sections: DegreeExamSection[];
}

function makeQuestion(
  id: string,
  number: number,
  prompt: string,
  analysis: Record<DegreeExamQuestionDetailKey, string>,
  options?: string[],
): DegreeExamQuestion {
  return { id, number, prompt, analysis, options };
}

